using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class UnevenDirtRoad {
static Vector3[] road;static float[] length;static Terrain terrain;static TerrainData before;
static Vector2 Nearest(float x,float z){var p=new Vector2(x,z);float best=999999,s=0;for(int i=1;i<road.Length;i++){var a=new Vector2(road[i-1].x,road[i-1].z);var d=new Vector2(road[i].x,road[i].z)-a;float t=Mathf.Clamp01(Vector2.Dot(p-a,d)/d.sqrMagnitude);float sq=(p-a-d*t).sqrMagnitude;if(sq<best){best=sq;s=Mathf.Lerp(length[i-1],length[i],t);}}return new Vector2(Mathf.Sqrt(best),s);}
static float Change(Vector3 p){var local=p-terrain.transform.position;return terrain.SampleHeight(p)-before.GetInterpolatedHeight(local.x/before.size.x,local.z/before.size.z);}
public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");string backup="Assets/NewMap/Terrain/Before road surface undulations.asset";if(File.Exists(backup))throw new Exception("Already applied; inspect before rerunning");var root=GameObject.Find("New_Map").transform;terrain=root.GetComponentInChildren<Terrain>();var td=terrain.terrainData;Directory.CreateDirectory("output/NewMap/RoadBumps");road=File.ReadAllLines("output/NewMap/Revision2/road-centerline.csv").Skip(1).Select(l=>{var s=l.Split(',');return new Vector3(float.Parse(s[0],System.Globalization.CultureInfo.InvariantCulture),float.Parse(s[1],System.Globalization.CultureInfo.InvariantCulture),float.Parse(s[2],System.Globalization.CultureInfo.InvariantCulture));}).ToArray();length=new float[road.Length];for(int i=1;i<road.Length;i++)length[i]=length[i-1]+Vector2.Distance(new Vector2(road[i].x,road[i].z),new Vector2(road[i-1].x,road[i-1].z));
AssetDatabase.CopyAsset(AssetDatabase.GetAssetPath(td),backup);before=AssetDatabase.LoadAssetAtPath<TerrainData>(backup);File.Copy("output/NewMap/Revision2/road-centerline.csv","output/NewMap/RoadBumps/centerline-before.csv",true);int n=td.heightmapResolution;var heights=td.GetHeights(0,0,n,n);float maxDelta=0;
for(int z=0;z<n;z++)for(int x=0;x<n;x++){float wx=terrain.transform.position.x+x/(float)(n-1)*td.size.x,wz=terrain.transform.position.z+z/(float)(n-1)*td.size.z;var near=Nearest(wx,wz);if(near.x>6.2f)continue;
float edge=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(3.6f,6.2f,near.x));float yard=Mathf.SmoothStep(0,1,Mathf.InverseLerp(39,58,new Vector2(wx,wz-14).magnitude));float village=Mathf.SmoothStep(0,1,Mathf.InverseLerp(30,48,new Vector2(wx-8,wz-175).magnitude));float s=near.y;
float roll=.18f*Mathf.Sin(s*2*Mathf.PI/25)+.055f*Mathf.Sin(s*2*Mathf.PI/9.5f+.8f);float crown=.10f*Mathf.Exp(-near.x*near.x/5);float ruts=-.035f*Mathf.Exp(-Mathf.Pow((near.x-1.1f)/.4f,2));float irregular=.035f*(Mathf.PerlinNoise(wx*.29f+80,wz*.29f+32)-.5f)*2;float delta=(roll+crown+ruts+irregular)*edge*yard*village;heights[z,x]+=delta/td.size.y;maxDelta=Mathf.Max(maxDelta,Mathf.Abs(delta));}
td.SetHeights(0,0,heights);terrain.Flush();int meshes=0,props=0;foreach(var f in root.Find("09_Original_Road_Details/Curved dirt ruts - original TFP meshes").GetComponentsInChildren<MeshFilter>(true)){var mesh=f.sharedMesh;var verts=mesh.vertices;for(int i=0;i<verts.Length;i++){var p=f.transform.TransformPoint(verts[i]);p.y+=Change(p);verts[i]=f.transform.InverseTransformPoint(p);}mesh.vertices=verts;mesh.RecalculateNormals();mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);meshes++;}
foreach(string group in new[]{"09_Original_Road_Details/Rocky road shoulders","05_Landscape/Original mixed grass and wildflowers","05_Landscape/Soft field verge"}){var parent=root.Find(group);if(!parent)continue;foreach(Transform t in parent){float delta=Change(t.position);if(Mathf.Abs(delta)>.001f){t.position+=Vector3.up*delta;props++;}}}
foreach(Transform t in root.Find("06_Road_Route")){var p=t.position;p.y=terrain.SampleHeight(p)+terrain.transform.position.y;t.position=p;}
for(int i=0;i<road.Length;i++)road[i].y=terrain.SampleHeight(road[i])+terrain.transform.position.y;var culture=System.Globalization.CultureInfo.InvariantCulture;File.WriteAllLines("output/NewMap/Revision2/road-centerline.csv",new[]{"x,y,z"}.Concat(road.Select(p=>p.x.ToString("F3",culture)+","+p.y.ToString("F3",culture)+","+p.z.ToString("F3",culture))));float maxGrade=0;for(int i=1;i<road.Length;i++){int samples=Mathf.CeilToInt(Vector3.Distance(road[i-1],road[i])/.4f);var previous=road[i-1];for(int j=1;j<=samples;j++){var p=Vector3.Lerp(road[i-1],road[i],j/(float)samples);p.y=terrain.SampleHeight(p)+terrain.transform.position.y;float distance=Vector2.Distance(new Vector2(p.x,p.z),new Vector2(previous.x,previous.z));if(distance>.001f)maxGrade=Mathf.Max(maxGrade,Mathf.Abs(p.y-previous.y)/distance);previous=p;}}
Physics.SyncTransforms();EditorUtility.SetDirty(td);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());string report="Actual terrain undulations and shallow crown/ruts added; maximum terrain displacement "+maxDelta.ToString("F3",culture)+"m; densely sampled max longitudinal road grade "+(100*maxGrade).ToString("F2",culture)+"%. "+meshes+" road detail meshes refitted and "+props+" roadside props regrounded. Farmyard and village entrances remain flat. Original terrain saved at "+backup+". Vehicle dynamics not playtested.";File.WriteAllText("output/NewMap/RoadBumps/summary.txt",report);return report;}
}
